"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";

function WarrantyForm() {
  const router = useRouter();

  const [serial, setSerial] =
    useState("");

  const [error, setError] =
    useState("");

  const [loading, setLoading] =
    useState(false);

  function handleChange(event) {
    const value =
      event.target.value
        .toUpperCase()
        .replace(/[^A-Z0-9]/g, "")
        .slice(0, 11);

    setSerial(value);
    setError("");
  }

  function handleSubmit(event) {
    event.preventDefault();

    if (!/^[A-Z0-9]{11}$/.test(serial)) {
      setError(
        "Serial number must contain exactly 11 letters or numbers."
      );

      return;
    }

    setLoading(true);

    router.push(
      `/warranty-result/${serial}`
    );
  }

  return (
    <div className="warranty-form">

      <p className="section-label">
        WARRANTY LOOKUP
      </p>

      <h2>
        Warranty Claim
      </h2>

      <p>
        Enter your 11-character product
        serial number to check warranty
        status and raise a claim.
      </p>

      <form onSubmit={handleSubmit}>

        <input
          type="text"
          value={serial}
          onChange={handleChange}
          placeholder="Enter 11-character serial number"
          maxLength={11}
          disabled={loading}
        />

        <button
          type="submit"
          disabled={loading}
        >
          {loading
            ? "Checking..."
            : "Submit"}
        </button>

      </form>

      <div className="serial-info">
        {serial.length}/11
      </div>

      {error && (
        <p className="error-message">
          {error}
        </p>
      )}

    </div>
  );
}

export default WarrantyForm;